def is_decorated_with_new_style_attrs(node) -> bool:
    """Return whether a decorated node has a new style attrs decorator applied.

    New style decorators are attrs.define, attrs.mutable, attrs.frozen and their
    attr.* equivalents, which support bare annotations.
    """
    if not node.decorators:
        return False
    for decorator_attribute in node.decorators.nodes:
        if isinstance(decorator_attribute, Call):  # decorator with arguments
            decorator_attribute = decorator_attribute.func
        if decorator_attribute.as_string() in ATTRS_NEW_STYLE_DECORATORS:
